// Decide (en código, no el modelo) cuál es el siguiente dato a pedir.
// Patrón "slot filling": el estado vive en la ficha del CRM; el modelo solo redacta.
// "si" activa un dato según otro (ej. la entrevista solo si eligió chat o pdf).
const cfg = $('Configuración del bot').item.json || {};
const ficha = $('Leer ficha').item.json || {};
const nuevos = $('Preparar datos').item.json.nuevos || {};
const lineas = String(ficha.datos || '').split('\n');
const entrev = (() => { try { return $('Leer entrevista').item.json || {}; } catch (e) { return {}; } })();
const slotsEntrevista = (entrev.preguntas || []).filter(s => s && s.clave).map(s => ({ ...s, entrevista: true,
  si: [{ clave: 'modo_entrevista', en: ['chat', 'pdf'] }].concat(s.si || []) }));
const slots = (cfg.conocer || []).filter(s => s && s.clave && !s.entrevista).concat(slotsEntrevista);
const valor = (s) => {
  if (nuevos[s.clave]) return nuevos[s.clave];
  if (s.clave === 'nombre') return String(ficha.nombre || '').trim();
  if (s.clave === 'negocio') return String(ficha.negocio || '').trim();
  const l = lineas.find(x => x.toLowerCase().startsWith(String(s.etiqueta || s.clave).toLowerCase() + ':'));
  return l ? l.slice(l.indexOf(':') + 1).trim() : '';
};
const val = (k) => { const s = slots.find(x => x.clave === k); return s ? valor(s) : ''; };
const cumple = (conds) => (conds || []).every(c => {
  const v = val(c.clave).toLowerCase();
  if (c.en) return c.en.some(x => v === String(x).toLowerCase());
  if (c.contiene) return v.includes(String(c.contiene).toLowerCase());
  return !!v;
});
const activo = (s) => cumple(s.si);
const activos = slots.filter(activo);
const ya = activos.filter(s => valor(s)).map(s => (s.etiqueta || s.clave) + ': ' + valor(s));
const faltan = activos.filter(s => !valor(s));
const listo = (s) => (s.requiere || []).every(k => { const r = slots.find(x => x.clave === k); return !r || valor(r); });
const noQuiere = $('Preparar datos').item.json.no_quiere || [];
// Con PDF el cliente contesta a su tiempo: el agente no hace las preguntas de la entrevista.
const modo = val('modo_entrevista').toLowerCase();
const preguntable = (s) => !(s.entrevista && modo === 'pdf');
// La entrevista la lleva el agente con su herramienta «entrevista»; aquí solo los datos de venta.
// «preguntar_si»: el dato se guarda siempre que el cliente lo diga, pero solo se pregunta si se cumple.
const entrevistaCompleta = slotsEntrevista.length > 0 && !faltan.some(s => s.entrevista);
const enEntrevista = modo === 'chat' && slotsEntrevista.length > 0 && !entrevistaCompleta;
const sig = enEntrevista ? null : (faltan.filter(s => !s.entrevista && !noQuiere.includes(s.clave) && preguntable(s) && cumple(s.preguntar_si)).find(listo) || null);
// Avisos de una sola vez para el agente: la entrevista se completó en este turno, o se acaba de mandar el PDF.
const pdfEnviado = String(nuevos.modo_entrevista || '').toLowerCase() === 'pdf' && !!cfg.entrevista_pdf;
let aviso = '';
if (pdfEnviado) aviso = ' Ya le mandamos el PDF con las preguntas: dile que puede contestar por escrito o con audios cuando tenga tiempo. No hagas las preguntas aquí.';
return { json: { ya: ya.join(' · '), siguiente: sig ? sig.pregunta : '', siguiente_clave: sig ? sig.clave : '',
  faltan: faltan.map(s => s.clave), no_quiere: noQuiere, modo_entrevista: modo, en_entrevista: enEntrevista, entrevista_completa: entrevistaCompleta, aviso } };

// Validador de salida (estilo Guardrails): una sola pregunta por mensaje.
const t = String($json.output || '');
const preguntas = (t.match(/¿[^?]*\?/g) || []).length || (t.match(/\?/g) || []).length;
return { json: { output: t, preguntas } };

// Datos que el modelo extrajo → solo los nuevos o cambiados de los datos activos.
const cfg = $('Configuración del bot').item.json || {};
const ficha = $('Leer ficha').item.json || {};
let ext = {};
// La cadena con respuesta JSON entrega el objeto ya armado; si llega como texto, se interpreta.
try { ext = typeof $json.text === 'string' ? JSON.parse($json.text.replace(/^```(?:json)?\s*|\s*```$/g, '')) : { ...$json }; } catch (e) { ext = {}; }
delete ext.type;
const FIJOS = ["nombre","negocio","giro","ciudad","reto","paquete","dia_llamada","correo","presupuesto","decide","para_cuando","notas"];
const entrev = (() => { try { return $('Leer entrevista').item.json || {}; } catch (e) { return {}; } })();
const slotsEntrevista = (entrev.preguntas || []).filter(s => s && s.clave).map(s => ({ ...s, entrevista: true,
  si: [{ clave: 'modo_entrevista', en: ['chat', 'pdf'] }].concat(s.si || []) }));
const slots = (cfg.conocer || []).filter(s => s && s.clave && !s.entrevista).concat(slotsEntrevista);
const lineas = String(ficha.datos || '').split('\n');
const actual = (s) => {
  if (s.clave === 'nombre') return String(ficha.nombre || '').trim();
  if (s.clave === 'negocio') return String(ficha.negocio || '').trim();
  const l = lineas.find(x => x.toLowerCase().startsWith(String(s.etiqueta || s.clave).toLowerCase() + ':'));
  return l ? l.slice(l.indexOf(':') + 1).replace(/\(por confirmar\)\s*$/i, '').trim() : '';
};
const limpio = (v) => (v === undefined || v === null) ? '' : String(v).trim();
// Valor vigente: lo que dijo ahora o lo que ya está en la ficha.
const val = (k) => { const s = slots.find(x => x.clave === k); return s ? (limpio(ext[k]) || actual(s)) : ''; };
const activo = (s) => (s.si || []).every(c => {
  const v = val(c.clave).toLowerCase();
  if (c.en) return c.en.some(x => v === String(x).toLowerCase());
  if (c.contiene) return v.includes(String(c.contiene).toLowerCase());
  return !!v;
});
const norm = (x) => String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
let dicho = '';
try { dicho = norm($('Juntar mensajes').item.json.texto); } catch (e) { dicho = ''; }
const nuevos = {};
const extra = {};
for (const s of slots) {
  if (!activo(s)) continue;
  const t = limpio(ext[s.clave]);
  if (!t || t.toLowerCase() === String(actual(s)).toLowerCase()) continue;
  // Un dato que ya estaba solo se cambia si el cliente lo acaba de escribir o decir (corrección).
  if (actual(s) && !dicho.includes(norm(t))) continue;
  if (FIJOS.includes(s.clave)) nuevos[s.clave] = t.slice(0, 300);
  else { nuevos[s.clave] = t.slice(0, 500); extra[s.etiqueta || s.clave] = t.slice(0, 500); }
}
const no_quiere = [].concat(ext.no_quiere || []).map(x => String(x).trim()).filter(Boolean);
// Pregunta de la entrevista que prefirió no contestar: queda marcada para no volver a pedirla.
for (const k of no_quiere) {
  const s = slotsEntrevista.find(x => x.clave === k);
  if (s && activo(s) && !actual(s)) { nuevos[k] = '(prefirió no contestar)'; extra[s.etiqueta || s.clave] = '(prefirió no contestar)'; }
}
return { json: { nuevos, extra, hay: Object.keys(nuevos).length > 0, no_quiere } };

// Revisar edición: el editor solo puede cambiar el tono. Si tocó cifras, links,
// nombres en negrita o la pregunta, o si alargó / recortó de más, se manda el borrador.
const borrador = String($('¿Hay respuesta?').item.json.output || '').trim();
let editado = '';
try {
  const r = typeof $json.text === 'string' ? JSON.parse($json.text.replace(/^```(?:json)?\s*|\s*```$/g, '')) : $json;
  editado = String((r && r.texto) || '').trim();
} catch (e) {}

const cifras = (s) => (s.match(/\d[\d.,:]*/g) || []).map((n) => n.replace(/[.,:]+$/, '').replace(/[.,]/g, '')).sort();
const links = (s) => (s.match(/https?:\/\/[^\s)]+/g) || []).sort();
const negritas = (s) => (s.match(/\*([^*\n]+)\*/g) || []).map((x) => x.replace(/\*/g, '').trim().toLowerCase());
const preguntas = (s) => (s.match(/¿[^?]*\?/g) || []).length || (s.match(/\?/g) || []).length;
const igual = (a, b) => JSON.stringify(a) === JSON.stringify(b);

const motivos = [];
if (!editado) motivos.push('sin respuesta del editor');
else {
  if (!igual(cifras(borrador), cifras(editado))) motivos.push('cambió cifras');
  if (!igual(links(borrador), links(editado))) motivos.push('cambió links');
  const plano = editado.replace(/\*/g, '').toLowerCase();
  if (negritas(borrador).some((n) => !plano.includes(n))) motivos.push('quitó un nombre en negrita');
  const pb = preguntas(borrador), pe = preguntas(editado);
  if (pb === 0 && pe > 0) motivos.push('agregó una pregunta');
  if (pb > 0 && pe !== 1) motivos.push('pregunta mal (' + pe + ')');
  if (editado.length > borrador.length * 1.15 + 30) motivos.push('lo alargó');
  if (borrador.length > 120 && editado.length < borrador.length * 0.35) motivos.push('recortó de más');
  if (/\[SIN_RESPUESTA\]/i.test(editado)) motivos.push('marca interna');
}

const usar = motivos.length === 0;
// Eco: primer párrafo corto que solo repite la respuesta del cliente ("Va, taquería.", "Aquí mismo, en Saltillo.").
const quitarEco = (txt) => {
  const partes = String(txt).split(/\n\s*\n/);
  if (partes.length < 2) return txt;
  const p0 = partes[0].trim();
  if (/\?|^mucho gusto|^(hola|buen[oa]s)/i.test(p0)) return txt;
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const vacias = new Set(['que','los','las','por','con','del','una','uno','para','pero','como','mas','muy','sus','esa','ese','eso','esta','este','todo','entonces','solo','aqui','mismo','sale','okey','bueno']);
  const pal = norm(p0).match(/[a-z0-9ñ]+/g) || [];
  if (pal.length === 0 || pal.length > 8) return txt;
  let cliente = '';
  try { cliente = norm($('Juntar mensajes').item.json.texto); } catch (e) {}
  const utiles = pal.filter(x => !vacias.has(x) && x !== 'va' && (x.length >= 3 || /\d/.test(x)));
  if (/[?¿]/.test(cliente)) return txt; // si preguntó algo, la primera frase puede ser la respuesta
  if (utiles.length === 0 || !utiles.some(x => cliente.includes(x))) return txt;
  return partes.slice(1).join('\n\n').trim();
};
const finalTxt = quitarEco(usar ? editado : borrador);
return {
  json: {
    output: finalTxt,
    borrador,
    editor: usar ? (editado === borrador ? 'sin cambios' : 'editado') : 'descartado: ' + motivos.join(', '),
  },
};
